using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation properties
        // or mutable values like DateTime.UtcNow (evaluated once at migration generation).
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: Cosmos provider now uses "$type" instead of "Discriminator".
        // For existing documents that already store "Discriminator", explicitly configure it:
        modelBuilder.Entity<Product>()
            .HasDiscriminatorInJsonProperty("Discriminator");

        modelBuilder.Entity<Product>()
            .HasPartitionKey(p => p.Category);
    }

    // EF Core 9 breaking change: Synchronous I/O on Cosmos is no longer supported.
    // All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.).
    public async Task<List<Product>> GetProductsAsync(string category)
        => await Products.Where(p => p.Category == category).ToListAsync();
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

